      function findReadyPair(events) {
        const anchors = events.锚点状态 ?? {};
        for (const pair of BRIDGE_PAIRS) {
          const from = anchors[pair.from] ?? {};
          const fromState = from.状态;
          const toState = anchors[pair.to]?.状态;
          const wrappedUp = fromState === '完成' || fromState === '变形' || fromState === '取消'
            || (fromState === '活跃' && from.收尾 === true);
          if (wrappedUp && toState === '未触发') return pair;
        }
        return null;
      }

      const root = document.currentScript?.closest('[data-wa-status-root]')
        ?? document.querySelector('[data-wa-status-root]');
      if (!root) return;
      const byId = id => root.querySelector(`#${id}`);
      const text = (id, value) => { const node = byId(id); if (node) node.textContent = value ?? '无'; };
      const asArray = value => Array.isArray(value) ? value : [];
      const clamp = value => Math.max(0, Math.min(100, Number(value) || 0));

      function updateAdvanceButton(events = renderedEvents) {
        const btn = byId('wa-advance-btn');
        if (!btn) return;
        renderedEvents = events ?? {};
        const pair = findReadyPair(events);
        const omenId = events.近期预兆?.事件ID;
        if (disposed) {
          btn.disabled = true;
          btn.textContent = '状态栏已卸载';
          btn.title = '';
        } else if (!currentIsLatest) {
          btn.disabled = true;
          btn.textContent = pair ? `历史楼层只读：${pair.to}` : '历史楼层只读';
          btn.title = '只有聊天中的最新楼层可以推进事件。';
        } else if (!mvuAvailable) {
          btn.disabled = true;
          btn.textContent = '等待 MVU 接口';
          btn.title = '尚未检测到宿主 MVU 接口。';
        } else if (!persistedDataReady) {
          btn.disabled = true;
          btn.textContent = '等待变量初始化';
          btn.title = '最新楼层尚无已持久化的 MVU 数据。';
        } else if (writeInFlight) {
          btn.disabled = true;
          btn.textContent = '正在推进，请稍候';
          btn.title = '事件写入进行中。';
        } else if (pair) {
          btn.disabled = false;
          btn.textContent = `推进：${pair.to} ${pair.title}`;
          btn.title = '手动确认推进：把下一事件写入预兆，预兆正文由叙事者下一轮描写。';
