      function relationWord(value, positive = true) {
        const score = clamp(value);
        if (!positive) {
          if (score >= 65) return '高度';
          if (score >= 30) return '明显';
          if (score > 0) return '轻微';
          return '无';
        }
        if (score >= 65) return '深厚';
        if (score >= 30) return '稳定';
        if (score > 0) return '初步';
        if (score <= -30) return '破裂';
        if (score < 0) return '疏离';
        return '未建立';
      }

      function makeMeter(label, value, negative = false) {
        const score = clamp(value);
        const row = document.createElement('div');
        row.className = 'wa-meter-row';
        const name = document.createElement('span');
        name.textContent = label;
        const track = document.createElement('span');
        track.className = 'wa-meter';
        const fill = document.createElement('span');
        fill.dataset.negative = String(negative);
        fill.style.left = '0%';
        fill.style.width = `${score}%`;
        track.append(fill);
        const words = document.createElement('span');
        words.className = 'wa-meter-text';
        words.textContent = `${score} · ${relationWord(Math.abs(score), negative)}`;
        row.append(name, track, words);
        return row;
      }

      function renderRelations(relations) {
        const container = byId('wa-relations');
        container.replaceChildren();
        const unlocked = Object.entries(relations ?? {}).filter(([, relation]) => relation?.解锁);
        if (!unlocked.length) {
          const empty = document.createElement('p');
          empty.className = 'wa-muted';
          empty.textContent = '尚无人物解锁。';
          container.append(empty);
          return;
