          situation.textContent = relation.处境 ?? '处境未知';
          const hasContact = relation.最近互动 && relation.最近互动 !== '无';
          if (hasContact) {
            body.append(meta, situation);
            body.append(
              makeMeter('好感', relation.好感),
              makeMeter('信赖', relation.信赖),
              makeMeter('戒备', relation.戒备, true),
              makeMeter('吸引', relation.吸引),
              makeMeter('创伤', relation.关系创伤, true),
              makeMeter('恶堕', relation.恶堕, true)
            );
            const cue = document.createElement('p');
            cue.className = 'wa-muted';
