          const detail = document.createElement('p');
          detail.className = 'wa-value wa-muted';
          detail.textContent = `${edge.当前状态 ?? '状态未明'}｜${edge.公开程度 ?? '公开程度未明'}｜${edge.最近变化 ?? '暂无变化'}`;
          row.append(title, detail);
          container.append(row);
        }
      }

      function updateUrgency(card, urgency) {
        card.classList.toggle('wa-card--urgent', urgency === '高' || urgency === '极高');
      }

      function render(data) {
        const state = data?.stat_data;
        if (!state) throw new Error('当前楼层还没有初始化变量');
        const world = state.世界 ?? {};
        const linen = state.林恩 ?? {};
        const system = state.系统 ?? {};
        const events = state.事件 ?? {};
        const activeSource = events.唯一活跃事件 ?? {};
        const hasActive = activeSource.状态 === '活跃' && Boolean(activeSource.事件ID);
        const active = hasActive ? activeSource : {
          事件ID: '', 标题: '', 地点: '', 参与者: [], 状态: '无', 紧迫度: '无', 模糊期限: '', 进展: '', 幕后停止点: '',
        };
        const omenSource = events.近期预兆 ?? {};
        const hasOmen = Boolean(omenSource.事件ID);
        const omen = hasOmen ? omenSource : {
          事件ID: '', 方向: '', 地点: '', 参与者: [], 紧迫度: '无', 模糊期限: '',
        };

        text('wa-phase', `${world.阶段编号 ?? '未知'} · ${world.阶段名称 ?? '阶段未知'}`);
        text('wa-phase-progress', `${world.模糊阶段进度 ?? '进度未知'}｜${world.氛围 ?? '氛围未知'}`);
        text('wa-location', world.地点);
        text('wa-time', world.当前场景时间);
        text('wa-linen', `17岁｜${linen.身体状况 ?? '身体状况未知'}`);
        const identityBox = byId('wa-identities');
        identityBox.replaceChildren();
        for (const identity of asArray(linen.当前身份)) {
          const chip = document.createElement('span');
          chip.className = 'wa-chip';
          chip.textContent = identity;
          identityBox.append(chip);
        }
        text('wa-task', `${system.当前任务 ?? '无'}｜${system.任务状态 ?? '无'}`);
        text('wa-task-note', `${linen.当前明确目标 ?? '目标未明确'}｜${system.任务说明 ?? '无说明'}`);
        text('wa-current-event', `${active.事件ID || '无'} ${active.标题 || '暂无活跃事件'}｜${active.紧迫度 ?? '无'}`);
        text('wa-current-event-progress', hasActive
          ? `${active.地点 || '地点未知'}｜${active.模糊期限 || '期限未知'}｜${active.进展 || '暂无进展'}`
          : '暂无活跃事件详情');
        updateUrgency(byId('wa-current-event-card'), active.紧迫度);

        renderRelations(state.关系);
        renderEdges(state.角色关系);

        text('wa-event-title', `${active.事件ID || '无'} ${active.标题 || '暂无活跃事件'}｜${active.状态 ?? '无'}｜紧迫度 ${active.紧迫度 ?? '无'}`);
        text('wa-event-detail', hasActive
          ? `${active.地点 || '地点未知'}｜参与者：${asArray(active.参与者).join('、') || '未知'}｜${active.模糊期限 || '期限未知'}｜${active.进展 || '暂无进展'}`
          : '暂无活跃事件详情');
        updateUrgency(byId('wa-event-detail-card'), active.紧迫度);

        text('wa-omen-title', `${omen.事件ID || '无预兆'}｜${omen.紧迫度 ?? '无'}`);
        text('wa-omen-detail', hasOmen
          ? `${omen.方向 || '方向待定'}｜${omen.地点 || '地点未知'}｜${omen.模糊期限 || '期限未知'}`
          : '暂无近期预兆');
        updateAdvanceButton(events);
        renderList(
          byId('wa-results'),
          asArray(events.最近结果).slice(-3).reverse().map(item => `${item.事件ID || '原创'} ${item.标题}：${item.结果}`),
          '暂无事件结果'
        );

        text('wa-sys-task', `${system.当前任务 ?? '无'}｜${system.任务状态 ?? '无'}`);
        text('wa-sys-task-stage', system.任务阶段 ?? '');
        text('wa-sys-task-note', system.任务说明 ?? '');
        text('wa-sys-level', `等级 ${linen.等级 ?? 1}`);
        const skillBox = byId('wa-sys-skills');
        skillBox.replaceChildren();
        for (const skill of asArray(linen.技能)) {
          const chip = document.createElement('span');
          chip.className = 'wa-chip';
          chip.textContent = skill;
          skillBox.append(chip);
        }
        renderList(byId('wa-sys-codex'), [...asArray(system.图鉴), ...asArray(linen.图鉴已解锁)], '图鉴尚未收录条目');
        renderList(byId('wa-sys-achievements'), [...asArray(system.成就), ...asArray(linen.成就)], '尚无成就');
        const evilBox = byId('wa-sys-evil');
        evilBox.replaceChildren();
        const unlockedPeople = Object.entries(state.关系 ?? {}).filter(([, relation]) => relation?.解锁);
        if (!unlockedPeople.length) {
          const empty = document.createElement('p');
          empty.className = 'wa-muted';
          empty.textContent = '尚无已解锁人物。';
          evilBox.append(empty);
        } else {
          for (const [name, relation] of unlockedPeople) {
            evilBox.append(makeMeter(name, relation.恶堕 ?? 0, true));
          }
        }
        text('wa-sys-notice', system.最近提示 ?? '');
        text('wa-sys-event-notice', system.事件通知 ?? '');

        byId('wa-error').hidden = true;
      }

      function showFallback(error) {
        const node = byId('wa-error');
        node.textContent = `等待变量初始化：当前仅显示初始预览，不会据此执行推进。${error?.message ? `（${error.message}）` : ''}`;
        node.hidden = false;
      }

      function showRuntimeError(message) {
        const node = byId('wa-error');
        node.textContent = message;
        node.hidden = false;
      }

      function getHostWindows() {
        const hosts = [globalThis];
        for (const candidate of [globalThis.parent, globalThis.top]) {
          try {
            if (candidate && !hosts.includes(candidate)) hosts.push(candidate);
          } catch {
            // 跨域父页面不可访问时继续使用当前窗口。
          }
        }
        return hosts;
      }

      function findMvu() {
        for (const host of getHostWindows()) {
          try {
            if (host.Mvu?.getMvuData) return host.Mvu;
          } catch {
            // 某一层窗口不可访问时继续向上查找。
          }
        }
        return undefined;
      }

      async function persistLatestMessageData(messageId, data) {
        const hosts = getHostWindows();
        const orderedHosts = [...hosts.filter(host => host !== globalThis), globalThis];
        let lastError;
        for (const host of orderedHosts) {
          try {
            const helper = host.TavernHelper;
            const tavern = host.SillyTavern;
            const context = typeof tavern?.getContext === 'function' ? tavern.getContext() : tavern;
            if (typeof helper?.setChatMessages !== 'function' || typeof context?.saveChat !== 'function') continue;
            await helper.setChatMessages([{ message_id: Number(messageId), data }], { refresh: 'none' });
            await context.saveChat();
            return;
          } catch (error) {
            lastError = error;
          }
        }
        throw lastError ?? new Error('宿主未提供消息变量保存接口');
      }

      async function waitForMvuBridge() {
        const deadline = Date.now() + 25000;
        let handshakeAttempted = false;
        while (!disposed && Date.now() < deadline) {
          let mvu = findMvu();
          if (mvu) return mvu;
          if (!handshakeAttempted && typeof waitGlobalInitialized === 'function') {
            handshakeAttempted = true;
            try {
              const remaining = Math.max(1, deadline - Date.now());
              await Promise.race([
                waitGlobalInitialized('Mvu'),
                new Promise((_, reject) => setTimeout(() => reject(new Error('MVU 初始化超时')), remaining)),
              ]);
            } catch (error) {
              showRuntimeError(`等待 MVU 初始化失败：${error?.message ?? error}`);
            }
            mvu = findMvu();
            if (mvu) return mvu;
          }
          await new Promise(resolve => setTimeout(resolve, 250));
        }
        return findMvu();
      }

      function getMessageId() {
        if (typeof getCurrentMessageId === 'function') return getCurrentMessageId();
        const match = String(globalThis.name || '').match(/^TH-message--(\d+)--/);
        return match ? Number(match[1]) : 'latest';
      }

      function getLatestMessageId() {
        for (const host of getHostWindows()) {
          try {
            const tavern = host.SillyTavern;
            const context = typeof tavern?.getContext === 'function' ? tavern.getContext() : tavern;
            const chat = context?.chat;
            if (!Array.isArray(chat)) continue;
            for (let index = chat.length - 1; index >= 0; index -= 1) {
              if (!chat[index]?.is_system) return index;
            }
          } catch {
            // 当前宿主入口不可用时尝试下一层窗口。
          }
        }
        return null;
      }

      function isLatestMessage(messageId) {
        if (messageId === 'latest') return true;
        const latestMessageId = getLatestMessageId();
        return Number.isInteger(messageId) && messageId === latestMessageId;
      }

      function unwrapMessageVariables(message) {
        const variables = message?.variables;
        if (!variables) return undefined;
        if (Array.isArray(variables)) return variables[message?.swipe_id ?? 0] ?? variables.at(-1);
        if (variables.stat_data) return variables;
        return variables[message?.swipe_id ?? 0];
      }

      function readStoredVariables(messageId) {
        for (const host of getHostWindows()) {
          try {
            const tavern = host.SillyTavern;
            const context = typeof tavern?.getContext === 'function' ? tavern.getContext() : tavern;
            const chat = context?.chat;
            if (!Array.isArray(chat) || !chat.length) continue;
            const startIndex = Number.isInteger(messageId)
              ? Math.min(messageId, chat.length - 1)
              : chat.length - 1;
            for (let index = startIndex; index >= 0; index -= 1) {
              const data = unwrapMessageVariables(chat[index]);
              if (data?.stat_data) return data;
            }
          } catch {
            // 当前宿主入口不可用时尝试下一层窗口。
          }
        }
        return undefined;
      }

      function readCurrent(mvu = findMvu()) {
        if (disposed) return;
        const messageId = getMessageId();
        currentIsLatest = isLatestMessage(messageId);
        mvuAvailable = Boolean(mvu);
        let data;
        let readError;
        try {
          data = mvu?.getMvuData({ type: 'message', message_id: messageId });
        } catch (error) {
          readError = error;
        }
        if (!data?.stat_data) data = readStoredVariables(messageId);
        persistedDataReady = Boolean(data?.stat_data);
        if (!persistedDataReady) {
          render({ stat_data: FALLBACK_STATE });
          showFallback(readError ?? new Error('当前楼层尚无已保存变量'));
          return;
        }
        render(data);
        byId('wa-error').hidden = true;
      }

      async function advanceCurrentEvent() {
        if (disposed || writeInFlight) return;
        const mvu = findMvu();
        if (!mvu) {
          mvuAvailable = false;
          updateAdvanceButton();
          showRuntimeError('推进不可用：未检测到宿主 MVU 接口。');
          return;
        }
        const messageId = getMessageId();
        currentIsLatest = isLatestMessage(messageId);
        if (!currentIsLatest) {
          updateAdvanceButton();
          showRuntimeError('历史楼层只读：请在聊天中的最新状态栏执行推进。');
          return;
        }

        writeInFlight = true;
        updateAdvanceButton();
        let succeeded = false;
        try {
          const data = mvu.getMvuData({ type: 'message', message_id: 'latest' });
          if (!data?.stat_data) {
            persistedDataReady = false;
            throw new Error('最新楼层尚无已持久化的 MVU 数据');
          }
          if (data.stat_data.事件?.近期预兆?.事件ID) {
            throw new Error(`已有近期预兆：${data.stat_data.事件.近期预兆.事件ID}`);
          }
          const pair = findReadyPair(data.stat_data.事件 ?? {});
          if (!pair) throw new Error('最新状态已变化，当前没有可推进事件');

          const state = JSON.parse(JSON.stringify(data.stat_data));
          const events = state.事件;
          const fromAnchor = events.锚点状态?.[pair.from];
          const toAnchor = events.锚点状态?.[pair.to];
          if (!fromAnchor || !toAnchor) throw new Error('事件锚点数据不完整');
          if (fromAnchor.状态 === '活跃') fromAnchor.状态 = '完成';
          if (['完成', '变形', '取消'].includes(fromAnchor.状态)) fromAnchor.收尾 = true;
          toAnchor.状态 = '预兆';
          toAnchor.收尾 = false;
          events.近期预兆 = {
            事件ID: pair.to,
            方向: pair.dir,
            地点: pair.loc,
            参与者: [],
            紧迫度: pair.urgency,
            模糊期限: pair.deadline,
          };
          const hasActive = Object.values(events.锚点状态).some(anchor => anchor.状态 === '活跃');
          if (!hasActive) {
            events.唯一活跃事件 = {
              事件ID: '', 标题: '', 地点: '', 参与者: [], 状态: '无', 紧迫度: '无', 模糊期限: '', 进展: '', 幕后停止点: '',
            };
          }
          state.系统 = state.系统 ?? {};
          state.系统.事件通知 = `${pair.to}已进入预兆：${pair.dir}`;
          const full = JSON.parse(JSON.stringify(data));
          full.stat_data = state;
          await mvu.replaceMvuData(full, { type: 'message', message_id: 'latest' });
          await persistLatestMessageData(getLatestMessageId(), full);
          persistedDataReady = true;
          succeeded = true;
        } catch (error) {
          showRuntimeError(`推进失败：${error?.message ?? error}`);
        } finally {
          writeInFlight = false;
          if (succeeded) readCurrent(mvu);
          else updateAdvanceButton();
        }
      }

      const tabs = [...root.querySelectorAll('[role="tab"]')];
      const uiAbortController = new AbortController();
      const uiSignal = uiAbortController.signal;
      function activateTab(next) {
        for (const tab of tabs) {
          const selected = tab === next;
          tab.setAttribute('aria-selected', String(selected));
          tab.tabIndex = selected ? 0 : -1;
          byId(tab.getAttribute('aria-controls')).hidden = !selected;
        }
      }
      tabs.forEach((tab, index) => {
        tab.addEventListener('click', () => activateTab(tab), { signal: uiSignal });
        tab.addEventListener('keydown', event => {
          if (!['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return;
          event.preventDefault();
          const offset = event.key === 'ArrowLeft' ? -1 : event.key === 'ArrowRight' ? 1 : 0;
          const nextIndex = event.key === 'Home' ? 0 : event.key === 'End' ? tabs.length - 1 : (index + offset + tabs.length) % tabs.length;
          tabs[nextIndex].focus();
          activateTab(tabs[nextIndex]);
        }, { signal: uiSignal });
      });

      const subscriptions = [];
      async function bootstrap() {
        readCurrent();
        const mvu = await waitForMvuBridge();
        if (disposed) return;
        if (!mvu) {
          mvuAvailable = false;
          persistedDataReady = false;
          updateAdvanceButton();
          showRuntimeError('状态栏无法连接 MVU 接口；请确认酒馆助手与卡内 MVU 脚本已启用。');
          return;
        }
        mvuAvailable = true;
        readCurrent(mvu);
        const advanceBtn = byId('wa-advance-btn');
        if (advanceBtn) advanceBtn.addEventListener('click', () => void advanceCurrentEvent(), { signal: uiSignal });
        if (mvu.events && typeof eventOn === 'function') {
          const refresh = () => { if (!disposed) readCurrent(mvu); };
          subscriptions.push(eventOn(mvu.events.VARIABLE_INITIALIZED, refresh));
          subscriptions.push(eventOn(mvu.events.VARIABLE_UPDATE_ENDED, refresh));
        }
      }
      window.addEventListener('pagehide', () => {
        disposed = true;
        uiAbortController.abort();
        subscriptions.forEach(subscription => subscription?.stop?.());
        subscriptions.length = 0;
      }, { once: true });
      void bootstrap();
    })();
  </script>
</section>
</body>
